python -c "
import sqlite3
conn = sqlite3.connect('/workspace/world.db')
cur = conn.cursor()
tables = cur.execute(\"SELECT name FROM sqlite_master WHERE type='table'\").fetchall()
print('Tables:', tables)
for t in tables:
    cols = cur.execute(f'PRAGMA table_info({t[0]})').fetchall()
    print(f'\n{t[0]} columns:', [c[1] for c in cols])
conn.close()
" 2>/dev/null || node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables);
tables.forEach(t => {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log(t.name + ':', cols.map(c => c.name));
});
db.close();
" 2>/dev/null || echo "No python or node sqlite available"

