cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

const user = db.prepare(\"SELECT * FROM users WHERE email = ?\").get('alicia.morgan@northbayconsulting.com');
if (user) {
  console.log('=== USER FOUND ===');
  console.log(JSON.stringify(user, null, 2));

  // Get payment methods
  const payments = db.prepare(\"SELECT * FROM rt_payment_methods WHERE user_id = ?\").all(user.user_id);
  console.log('\\n=== PAYMENT METHODS ===');
  console.log(JSON.stringify(payments, null, 2));

  // Get order details for ORD-66CC25
  const order = db.prepare(\"SELECT * FROM orders WHERE order_id = ? AND customer_id = ?\").get('ORD-66CC25', user.user_id);
  console.log('\\n=== ORDER ORD-66CC25 ===');
  console.log(JSON.stringify(order, null, 2));

  // Get order items
  const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = ?\").all('ORD-66CC25');
  console.log('\\n=== ORDER ITEMS ===');
  console.log(JSON.stringify(items, null, 2));

  // Get fulfillments
  const fulfillments = db.prepare(\"SELECT * FROM order_fulfillments WHERE order_id = ?\").all('ORD-66CC25');
  console.log('\\n=== FULFILLMENTS ===');
  console.log(JSON.stringify(fulfillments, null, 2));

  // Get payment history
  const orderPayments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = ?\").all('ORD-66CC25');
  console.log('\\n=== ORDER PAYMENTS ===');
  console.log(JSON.stringify(orderPayments, null, 2));
} else {
  console.log('User not found');
}
"

